  docs_gs_title: 'Bienvenido a cforj Studio',
  docs_gs_desc: 'cforj Studio es un constructor de aplicaciones de aprendizaje sin código que te permite crear cursos interactivos, cuestionarios y contenido de formación, y luego exportar como paquetes SCORM, archivos HTML o incrustar directamente en tu sitio web.',
