  docs_gs_arch_title: 'Arquitectura',
  docs_gs_arch_desc: 'Los cursos se almacenan en un formato basado en JSON llamado course.json. Este formato es compatible con git, portátil y diseñado para lectura automática.',
  docs_qs_title: 'Inicio rápido',
  docs_qs_desc: 'Crea tu primer curso en menos de 5 minutos.',
  docs_qs_step1_title: 'Paso 1: Crear un curso',
  docs_qs_step1_desc: 'Haz clic en "Nuevo curso" en el panel. Se crea automáticamente un curso en blanco con una pantalla.',
