  docs_qs_step2_desc: 'Haz clic en el botón "+ Añadir" en el lienzo para agregar componentes. Elige entre bloques de texto, imágenes, videos, cuestionarios y elementos interactivos.',
  docs_qs_step3_title: 'Paso 3: Configurar pantallas',
  docs_qs_step3_desc: 'Usa el panel izquierdo para gestionar pantallas. Arrastra para reordenar, haz clic en "+" para añadir nuevas pantallas. Organiza en módulos para cursos largos.',
