  docs_gs_title: 'Bem-vindo ao cforj Studio',
  docs_gs_desc: 'cforj Studio é um construtor de aplicativos de aprendizagem sem código que permite criar cursos interativos, questionários e conteúdo de treinamento — depois exportar como pacotes SCORM, arquivos HTML ou incorporar diretamente no seu site.',
  docs_gs_tip: 'Pense nisso como "Tilda para aprendizagem" — projetado para especialistas no assunto, não apenas para designers instrucionais.',
