  docs_gs_feat_scorm: 'Exportação SCORM',
  docs_gs_feat_scorm_desc: 'envie para qualquer LMS (Moodle, iSpring, TalentLMS, etc.)',
  docs_gs_feat_embed: 'Incorporar em qualquer lugar',
