  docs_gs_arch_title: 'Arquitetura',
  docs_gs_arch_desc: 'Os cursos são armazenados em um formato baseado em JSON chamado course.json. Este formato é compatível com git, portátil e projetado para leitura por máquinas.',
  docs_qs_title: 'Início rápido',
  docs_qs_desc: 'Crie seu primeiro curso em menos de 5 minutos.',
  docs_qs_step1_title: 'Passo 1: Criar um curso',
  docs_qs_step1_desc: 'Clique em "Novo curso" no painel. Um curso em branco com uma tela é criado automaticamente.',
  docs_qs_step2_title: 'Passo 2: Adicionar conteúdo',
  docs_qs_step2_desc: 'Clique no botão "+ Adicionar" na tela para adicionar componentes. Escolha entre blocos de texto, imagens, vídeos, questionários e elementos interativos.',
  docs_qs_step3_title: 'Passo 3: Configurar telas',
  docs_qs_step3_desc: 'Use o painel esquerdo para gerenciar telas. Arraste para reordenar, clique "+" para adicionar novas telas. Organize em módulos para cursos longos.',
  docs_qs_step4_title: 'Passo 4: Pré-visualização',
  docs_qs_step4_desc: 'Clique em "Pré-visualização" no cabeçalho para ver como seu curso aparece e funciona para os alunos.',
  docs_qs_step5_title: 'Passo 5: Exportar',
  docs_qs_step5_desc: 'Use o menu de exportação para baixar como SCORM (para LMS), HTML (arquivo independente) ou copie o código de incorporação para seu site.',
  docs_qs_tip: 'Use os atalhos de teclado Ctrl+Z / Ctrl+Y para desfazer/refazer alterações durante a edição.',
